var i=`0146-lahmajo`;var t=`world-0146`;var o=`AM`;var a=`western-asia`;var s=4;var r=81;var l={en:`Lahmajo`,ua:`Ламаджо`};var g={en:`A classic dish from Armenia, featuring ground lamb, yellow onion, tomato, parsley. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Вірменія. Основні складники: фарш з ягнятини, жовта цибуля, помідор, петрушка. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var h=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 35 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 35 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:35,i:[[`all-purpose-flour`,470,`g`],[`water`,245,`ml`],[`instant-yeast`,5,`g`],[`table-salt`,5,`g`],[`extra-virgin-olive-oil`,25,`ml`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:10,i:[[`ground-lamb`,480,`g`],[`yellow-onion`,210,`g`],[`tomato`,240,`g`],[`parsley`,35,`g`],[`tomato-paste`,30,`g`],[`sweet-paprika`,9,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:22,i:[]},{en:`Bake in a thoroughly preheated 230–250°C oven for about 12 minutes until the crust is deeply golden and the filling is cooked.`,ua:`Випікайте в добре розігрітій до 230–250°C духовці приблизно 12 хвилин до насичено-золотистої скоринки та готовності начинки.`,t:[`high-temperature-roasting`,`baking`],m:12,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`lemon`,2,`pcs`]]}];var d={slug:i,id:t,country:`AM`,region:a,servings:4,minutes:81,title:l,text:g,steps:h};export{o as country,d as default,t as id,r as minutes,a as region,s as servings,i as slug,h as steps,g as text,l as title};